"""Staged executor: runs a BoundQuery in the contract evaluation order and returns a Result."""
from __future__ import annotations

from . import evaluate as ev
from .errors import QueryRuntimeError
from .plan import (
    BAggRef, BArith, BCol, BCompare, BGroupRef, BIn, BIsNull, BLike, BLit, BLogical, BNot,
    BoundQuery, BUnary,
)
from .result import Result


def _compile(node, sql):
    """Bound expression -> closure over `env`: a flat row tuple (row level) or (keys, aggs) (group level)."""
    t = type(node)
    if t is BCol:
        i = node.index
        return lambda env: env[i]
    if t is BLit:
        v = node.value
        return lambda env: v
    if t is BGroupRef:
        i = node.index
        return lambda env: env[0][i]
    if t is BAggRef:
        i = node.index
        return lambda env: env[1][i]
    if t is BUnary:
        f = _compile(node.operand, sql)
        op = ev.negate if node.op == '-' else ev.plus
        return lambda env: op(f(env))
    if t is BArith:
        lf, rf = _compile(node.left, sql), _compile(node.right, sql)
        op, real, pos = node.op, node.real, node.pos

        def arith(env):
            a = lf(env)
            b = rf(env)
            try:
                return ev.arith(op, a, b, real)
            except ev.DivisionByZero:
                raise QueryRuntimeError.at(sql, pos, 'division by zero') from None
        return arith
    if t is BCompare:
        lf, rf, op = _compile(node.left, sql), _compile(node.right, sql), node.op

        def compare(env):
            a = lf(env)
            return ev.compare(op, a, rf(env))
        return compare
    if t is BLogical:
        lf, rf = _compile(node.left, sql), _compile(node.right, sql)
        if node.op == 'AND':
            def and_(env):
                a = lf(env)
                if ev.truthy(a) is False:
                    return 0
                return ev.combine_and(a, rf(env))
            return and_

        def or_(env):
            a = lf(env)
            if ev.truthy(a):
                return 1
            return ev.combine_or(a, rf(env))
        return or_
    if t is BNot:
        f = _compile(node.operand, sql)
        return lambda env: ev.not3(f(env))
    if t is BIsNull:
        f = _compile(node.operand, sql)
        if node.negated:
            return lambda env: 0 if f(env) is None else 1
        return lambda env: 1 if f(env) is None else 0
    if t is BLike:
        vf, pf = _compile(node.operand, sql), _compile(node.pattern, sql)
        escape, negated, pos = node.escape, node.negated, node.pos

        def like(env):
            v = vf(env)
            p = pf(env)
            try:
                r = ev.like(v, p, escape)
            except ev.InvalidLikePattern:
                raise QueryRuntimeError.at(sql, pos, 'invalid LIKE pattern') from None
            return ev.not3(r) if negated else r
        return like
    if t is BIn:
        xf = _compile(node.operand, sql)
        item_fs = [_compile(i, sql) for i in node.items]
        negated = node.negated

        def in_(env):
            x = xf(env)
            r = ev.in_list(x, [f(env) for f in item_fs])
            return ev.not3(r) if negated else r
        return in_
    raise TypeError('unknown bound node %r' % (node,))


def _true(f):
    """Row filter predicate: keep only rows whose condition is true (not false, not NULL)."""
    return lambda env: ev.truthy(f(env)) is True


def _aggregate(func, values):
    """Final aggregate value from the argument values (None for COUNT(*) rows) collected in row order."""
    if func == 'COUNT':
        return sum(1 for v in values if v is not None) if values and values[0] is not _STAR else len(values)
    total = None
    count = 0
    for v in values:
        if v is None:
            continue
        count += 1
        if total is None:
            total = v
        elif func in ('SUM', 'AVG'):
            total = total + v
        elif (func == 'MIN' and v < total) or (func == 'MAX' and v > total):
            total = v
    if func == 'AVG' and total is not None:
        return total / count
    return total


_STAR = object()  # placeholder argument value for COUNT(*)


def execute(bound: BoundQuery, sql: str) -> Result:
    c = lambda node: _compile(node, sql)  # noqa: E731

    # 1. FROM / joins (nested loop).
    if bound.tables:
        rows = list(bound.tables[0].rows)
        for (kind, on), table in zip(bound.joins, bound.tables[1:]):
            on_f = _true(c(on))
            fill = (None,) * len(table.columns)
            joined = []
            for left in rows:
                matched = False
                for right in table.rows:
                    row = left + right
                    if on_f(row):
                        joined.append(row)
                        matched = True
                if not matched and kind == 'LEFT':
                    joined.append(left + fill)
            rows = joined
    else:
        rows = [()]

    # 2. WHERE.
    if bound.where is not None:
        where_f = _true(c(bound.where))
        rows = [r for r in rows if where_f(r)]

    # 3-4. Grouping and aggregates, then HAVING; envs are rows or (keys, aggs) groups.
    if bound.is_aggregate:
        key_fs = [c(g) for g in bound.group_by]
        arg_fs = [(lambda env: _STAR) if a.arg is None else c(a.arg) for a in bound.aggregates]
        groups = {} if bound.group_by else {(): [[] for _ in arg_fs]}
        for r in rows:
            key = tuple(f(r) for f in key_fs)
            args = [f(r) for f in arg_fs]
            acc = groups.get(key)
            if acc is None:
                acc = groups[key] = [[] for _ in arg_fs]
            for lst, v in zip(acc, args):
                lst.append(v)
        envs = [
            (key, tuple(_aggregate(a.func, vals) for a, vals in zip(bound.aggregates, acc)))
            for key, acc in groups.items()
        ]
        if bound.having is not None:
            having_f = _true(c(bound.having))
            envs = [e for e in envs if having_f(e)]
    else:
        envs = rows

    # 5. Select expressions.
    select_fs = [c(s) for s in bound.select]
    projected = [tuple(f(e) for f in select_fs) for e in envs]

    # 6. ORDER BY keys ('expr' keys evaluated per row/group; 'output' keys read the projection).
    order_fs = [c(o.expr) if o.kind == 'expr' else None for o in bound.order]
    keys = [
        tuple(p[o.index] if f is None else f(e) for o, f in zip(bound.order, order_fs))
        for e, p in zip(envs, projected)
    ]
    items = list(zip(projected, keys))

    # 7. DISTINCT (first occurrence kept; NULL equals NULL).
    if bound.distinct:
        seen = set()
        kept = []
        for item in items:
            if item[0] not in seen:
                seen.add(item[0])
                kept.append(item)
        items = kept

    # 8. Stable sort, last key first; NULL smallest.
    for k in range(len(bound.order) - 1, -1, -1):
        items.sort(key=lambda it: (it[1][k] is not None, it[1][k]), reverse=bound.order[k].desc)

    # 9. OFFSET, then LIMIT.
    out = [p for p, _ in items]
    if bound.offset is not None:
        out = out[bound.offset:]
    if bound.limit is not None:
        out = out[:bound.limit]
    return Result(list(bound.columns), list(bound.types), out)

"""Library API: connect(data_dir) -> Connection with execute / tables / schema."""
from __future__ import annotations

import sys
from typing import List, Tuple

from .analyzer import analyze
from .catalog import Catalog
from .errors import MiniSQLError, QueryRuntimeError, SemanticError
from .executor import execute
from .result import Result
from .sqlparser import parse

_RECURSION_LIMIT = 10000


def connect(data_dir) -> "Connection":
    """`data_dir` is a str or os.PathLike; a missing or non-directory path raises DataIOError now."""
    return Connection(data_dir)


class Connection:
    def __init__(self, data_dir):
        self._catalog = Catalog(data_dir)

    def execute(self, sql: str) -> Result:
        old = sys.getrecursionlimit()
        sys.setrecursionlimit(max(old, _RECURSION_LIMIT))
        try:
            return execute(analyze(parse(sql), sql, self._catalog), sql)
        except MiniSQLError:
            raise
        except Exception as exc:  # D19: RecursionError, OverflowError, int/str limits, ...
            raise QueryRuntimeError(str(exc) or type(exc).__name__, 1, 1) from None
        finally:
            sys.setrecursionlimit(old)

    def tables(self) -> List[str]:
        return self._catalog.table_names()

    def schema(self, table: str) -> List[Tuple[str, str]]:
        t = self._catalog.load(table)
        if t is None:
            raise SemanticError("unknown table '%s'" % table, 1, 1)
        return list(zip(t.columns, t.types))

